class MainView implements View<MainState, MainMsg, AppCtx> {
  container: HTMLElement;
  private b: Binder<MainState>;
  private ctx: AppCtx;

  constructor(
    container: HTMLElement,
    dispatch: (msg: MainMsg) => void,
    initialState: MainState,
    ctx: AppCtx,
  ) {
    this.container = container;
    this.ctx = ctx;

    const headerRef = ref("header");
    const crumbsRef = ref("crumbs");
    const mainRef = ref("main");

    container.innerHTML = sanitize`
      <div class="${rootClass}">
        <div data-ref="${headerRef}"></div>
        <div data-ref="${crumbsRef}"></div>
        <main data-ref="${mainRef}"></main>
      </div>
    `;

    this.b = new Binder(container, initialState);

    this.b.bindSlot(headerRef, (): SlotContent | undefined => {
      const header = headerStateFor(this.ctx.router.route, this.ctx.auth.get());
      return header === undefined
        ? undefined
        : show(
            AppHeaderView,
            header,
            { dismissStack: this.ctx.dismissStack },
            (m) => dispatch(m),
          );
    });

    this.b.bindSlot(crumbsRef, (s) =>
      navHidden(this.ctx.router.route, this.ctx.auth.get())
        ? undefined
        : show(
            BreadcrumbsView,
            { crumbs: crumbsForPage(s.pageState) },
            {},
            noop,
          ),
    );
    this.b.bindStyle(
      mainRef,
      (): Record<string, string> =>
        navHidden(this.ctx.router.route, this.ctx.auth.get())
          ? { padding: "0" }
          : {},
    );
    // Most pages render inside the centered reading column; full-bleed shells
    // (the calendar's three-pane layout) and the nav-hidden public pages opt out.
    this.b.bindClass(mainRef, (s) =>
      navHidden(this.ctx.router.route, this.ctx.auth.get()) ||
      s.pageState.page === "calendar" ||
      s.pageState.page === "search"
        ? ""
        : centeredColumn,
    );
    this.b.bindSlot(mainRef, (s) => pageSlot(s, this.ctx, dispatch));
  }

  sync(state: MainState): void {
    this.b.sync(state);
  }

  destroy(): void {
    this.b.cleanup();
    this.container.innerHTML = "";
  }
}

async function startApp(container: HTMLElement) {
  const initialRoute = currentRoute();
  const initialAuth = await resolveInitialAuth();

  // Seed the active back-office org slug. If the URL named an <orgSlug>
  // (`/org/<orgSlug>/…`), parseRoute already set it; otherwise fall back to the
  // resolved active org so back-office links/URLs build correctly.
  if (getCurrentOrgSlug() === null && initialAuth.status === "authed") {
    const active = resolveActiveOrg(initialAuth.me);
    if (active) setCurrentOrgSlug(active.slug);
  }

  let dispatching = false;
  function dispatch(msg: MainMsg): void {
    if (dispatching) throw new Error("dispatch-in-dispatch");
    dispatching = true;
    update(state, msg, ctx, dispatch);
    view.sync(state);
    routerView.sync();
    ctx.postRenderBus.flush();
    dispatching = false;
  }

  const ctx = createAppCtx(api, dispatch, initialRoute, initialAuth);

  const state: MainState = {
    pageState: { page: "login" },
  };

  // Resolve the same auth redirect rules as in-app navigation; the controller
  // now owns the route, and routerView.sync() below writes any redirect URL.
  const route = ctx.router.update({ type: "NAVIGATE", route: initialRoute });
  state.pageState = pageStateFor(route, ctx.auth.get());

  const view = new MainView(container, dispatch, state, ctx);
  const routerView = new RouterView(ctx.router, (m) =>
    dispatch({ type: "NAVIGATE", route: m.route }),
  );

  routerView.sync();
  routerView.mount();

  if (route.page === "search" || route.page === "calendar") {
    ctx.searchStore.update({ type: "RESET", params: route.params }, (m) =>
      dispatch({ type: "SEARCH_STORE_MSG", msg: m }),
    );
  }
}

function renderBootError(container: HTMLElement): void {
  container.innerHTML = "";
  const wrap = document.createElement("div");
  wrap.className = "boot-error";
  wrap.setAttribute("role", "alert");

  const heading = document.createElement("h1");
  heading.textContent = "Something went wrong";
  const body = document.createElement("p");
  body.textContent =
    "We couldn't reach the server. Please try again in a moment.";
  const retry = document.createElement("button");
  retry.type = "button";
  retry.textContent = "Retry";
  retry.addEventListener("click", () => {
    window.location.reload();
  });

  wrap.append(heading, body, retry);
  container.append(wrap);
}

const root = document.getElementById("app") ?? document.body;
startApp(root).catch((e: unknown) => {
  console.error(e);
  renderBootError(root);
});

import path from "node:path";
import { fileURLToPath } from "node:url";
import dotenv from "dotenv";
import { createApp } from "./create-app.ts";
import { createPool } from "./db/connect.ts";
import { createConsoleSender, createResendSender } from "./email/send.ts";
import { readEnv } from "./env.ts";
import { createMessageWorker } from "./messages/worker.ts";
import { createMeili } from "./search/meili.ts";
import { createIncrementalReindexWorker } from "./search/reindex-worker.ts";

const __filename = fileURLToPath(import.meta.url);
const __dirname = path.dirname(__filename);

dotenv.config({ path: path.join(__dirname, "../../.env") });

async function run() {
  const env = readEnv();
  const pool = createPool(env.DATABASE_URL);
  const email =
    env.RELEASE_STAGE === "prod"
      ? createResendSender(env.RESEND_API_KEY, env.FROM_EMAIL)
      : createConsoleSender();
  const meili = createMeili(env);
  const app = await createApp({ pool, env, email, meili });

  // The background incremental reindex worker lives ONLY here, in the prod
  // entry point — deliberately not in `createApp`. Tests (backend vitest +
  // e2e) build the app via `createApp` and so never start it: search reindexing
  // in tests is explicit and on-demand via the org-scoped helpers
  // (`reindexOrg` / `reindexOrgIncremental`). `createApp` only `ensureLiveIndex`
  // at boot so the app starts with an empty, settings-applied live index.
  const searchWorker = createIncrementalReindexWorker(
    pool,
    meili,
    env.MEILI_INDEX_NAMESPACE,
  );

  // The email send/render worker: forms <=100-member batches from unbatched
  // pending messages, renders them, and drains them to Resend with backoff. Like
  // the search worker it lives ONLY in the prod entry point, never in
  // createApp — tests drive it explicitly via `createMessageWorker(...).drainOnce()`.
  const messageWorker = createMessageWorker(pool, email, env);
  messageWorker.start();

  searchWorker.start();
  for (const signal of ["SIGINT", "SIGTERM"] as const) {
    process.once(signal, () => {
      void Promise.all([searchWorker.stop(), messageWorker.stop()]).then(() =>
        app.close(),
      );
    });
  }

  const PORT = parseInt(process.env.PORT || "3000", 10);
  await app.listen({ port: PORT, host: "0.0.0.0" });
  console.log(`gatherus running on port ${PORT}`);
}

run().catch((err) => {
  console.error(err);
  process.exit(1);
});

